import React, { useState, useEffect, useRef } from "react";
import { supabase } from "./supabase";

/* ============================================================================
   JUVENTUDE 40 GRAUS — Agente de IA de Políticas Públicas de Juventude
   JSB Ceará · ciclo 2026
   Identidade visual oficial (paleta IDV, fonte Boldonse, logo real, sunburst).
============================================================================ */

const LOGO_BANNER = "data:image/jpeg;base64,";

// ---- Paleta oficial da IDV (extraída do brandbook) ----
const C = {
  laranja: "#F26A0F",
  laranjaEsc: "#D6510A",
  vermelho: "#E5321A",
  dourado: "#F8B00A", // o "40" e detalhes
  amarelo: "#FBC91A", // highlights
  creme: "#FBF3E4",
  cremeD: "#EFE0C2",
  tinta: "#1F1917",
  tintaSoft: "#3A302A",
  branco: "#FFFDF8",
};

// sunburst quente da IDV (raios de sol + grão) — usado em barras e destaques
const SUNBURST = {
  backgroundColor: C.laranja,
  backgroundImage: `radial-gradient(circle at 50% -10%, rgba(251,201,26,.45), rgba(251,201,26,0) 55%), repeating-conic-gradient(from 0deg at 50% -8%, rgba(255,255,255,.07) 0deg 5deg, rgba(255,255,255,0) 5deg 11deg), linear-gradient(165deg, ${C.laranja}, ${C.laranjaEsc})`,
};

const TEMAS = [
  "Educação",
  "Trabalho e Renda",
  "Cultura e Esporte",
  "Saúde e Saúde Mental",
  "Meio Ambiente",
  "Segurança e Direitos",
  "Mobilidade e Cidade",
  "Participação e Juventude",
  "Outro",
];

const TEMA_COR = {
  "Educação": "#E5321A",
  "Trabalho e Renda": "#F26A0F",
  "Cultura e Esporte": "#C81E7E",
  "Saúde e Saúde Mental": "#1F9E63",
  "Meio Ambiente": "#158A48",
  "Segurança e Direitos": "#6A3AD1",
  "Mobilidade e Cidade": "#1668D8",
  "Participação e Juventude": "#E08A00",
  "Outro": "#6B5545",
};

// A chave do Gemini e o modelo ficam no servidor (api/chat.js). Nenhum segredo aqui.

const SYSTEM_CHAT = `Você é o "Sol", o agente de IA da Juventude 40 Graus — iniciativa da juventude do Ceará para reunir ideias de políticas públicas de juventude no ciclo 2026.

Seu papel: conversar com um jovem (16 a 35 anos) de um jeito acolhedor, animado e nordestino, e ajudá-lo a transformar o que ele sente/vive numa proposta concreta de política pública.

Regras:
- Fale português do Brasil, tom jovem, caloroso e direto. Frases curtas. Nada de textão.
- Faça UMA pergunta por vez. Comece descobrindo o que mais incomoda ou o que ele mudaria pra juventude da cidade dele.
- Ajude a deixar a ideia concreta: qual é o problema, quem é afetado, e o que fazer na prática.
- Se a pessoa fugir muito do tema (juventude/cidade/Ceará), traga de volta com gentileza.
- Não puxe pra nenhum partido nem faça propaganda. A ideia é da pessoa — você só ajuda a lapidar.
- Quando sentir que a ideia já está redonda, incentive: "Boa! Quando quiser, é só tocar em Enviar minha proposta aqui embaixo 🔥".
- Nunca invente dados. Se não souber, tudo bem.`;

const SYSTEM_EXTRACT = `Você recebe uma conversa entre um jovem e um agente. Extraia UMA proposta de política pública de juventude.
Responda APENAS com um objeto JSON válido (sem texto antes/depois, sem markdown, sem crases), com estes campos:
{
 "titulo": "título curto e chamativo (máx 8 palavras)",
 "tema": "um destes exatos: ${TEMAS.join(" | ")}",
 "problema": "o problema em 1-2 frases, na voz do jovem",
 "proposta": "o que fazer na prática, 1-3 frases",
 "beneficiarios": "quem se beneficia (curto)",
 "nome": "primeiro nome se aparecer, senão \\"\\"",
 "cidade": "cidade se aparecer, senão \\"\\"",
 "idade": "idade se aparecer, senão \\"\\""
}
Se algum campo não existir na conversa, use string vazia. Nunca invente cidade, nome ou idade.`;

// ---- Agente de IA via nosso servidor (Gemini, chave protegida) ----
async function callAgent(messages, system) {
  const res = await fetch("/api/chat", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ system, messages }),
  });
  if (!res.ok) throw new Error("api");
  const data = await res.json();
  return (data.text || "").trim();
}

// ---- Dados no Supabase ----
async function listMural() {
  const { data, error } = await supabase.from("mural").select("*").order("criado_em", { ascending: false });
  if (error) return [];
  return data || [];
}
async function listDossie() {
  const { data, error } = await supabase.from("ideias").select("*").order("criado_em", { ascending: false });
  if (error) return [];
  return data || [];
}
async function saveIdeia(idea) {
  const { error } = await supabase.from("ideias").insert(idea);
  if (error) throw error;
  return true;
}

// ---- Sol mascote (SVG) ----
function Sol({ size = 44 }) {
  const rays = Array.from({ length: 12 });
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true">
      {rays.map((_, i) => {
        const a = (i * 30 * Math.PI) / 180;
        return (
          <line
            key={i}
            x1={50 + Math.cos(a) * 34}
            y1={50 + Math.sin(a) * 34}
            x2={50 + Math.cos(a) * 47}
            y2={50 + Math.sin(a) * 47}
            stroke={C.amarelo}
            strokeWidth="6"
            strokeLinecap="round"
          />
        );
      })}
      <circle cx="50" cy="50" r="30" fill={C.dourado} stroke={C.tinta} strokeWidth="4" />
      <rect x="30" y="42" width="16" height="12" rx="4" fill={C.tinta} />
      <rect x="54" y="42" width="16" height="12" rx="4" fill={C.tinta} />
      <rect x="46" y="46" width="8" height="3" fill={C.tinta} />
      <path d="M40 62 Q50 72 60 62" stroke={C.tinta} strokeWidth="4" fill="none" strokeLinecap="round" />
    </svg>
  );
}

// ---- Contorno do Ceará (traço amarelo, como no logo) ----
function CearaOutline({ size = 46, color }) {
  return (
    <svg width={size} height={size * 0.8} viewBox="0 0 300 240" aria-hidden="true" fill="none">
      <path
        d="M55 80 Q82 58 112 71 Q138 82 162 63 Q196 44 226 68 Q242 102 223 134 Q210 166 186 191 Q160 219 139 205 Q119 190 107 160 Q91 127 77 110 Q63 95 55 80 Z"
        stroke={color || C.amarelo}
        strokeWidth="8"
        strokeLinejoin="round"
        strokeLinecap="round"
      />
    </svg>
  );
}

// ---- Bolha de chat ----
function Bubble({ role, children }) {
  const me = role === "user";
  return (
    <div style={{ display: "flex", justifyContent: me ? "flex-end" : "flex-start", marginBottom: 12 }}>
      {!me && (
        <div style={{ marginRight: 8, flexShrink: 0, alignSelf: "flex-end" }}>
          <Sol size={28} />
        </div>
      )}
      <div
        style={{
          maxWidth: "82%",
          padding: "11px 14px",
          borderRadius: 20,
          borderBottomRightRadius: me ? 5 : 20,
          borderBottomLeftRadius: me ? 20 : 5,
          background: me ? C.tinta : C.branco,
          color: me ? C.branco : C.tinta,
          border: me ? "none" : `1.5px solid ${C.cremeD}`,
          boxShadow: me ? "none" : "0 1px 2px rgba(31,25,23,.06)",
          fontSize: 15,
          lineHeight: 1.45,
          whiteSpace: "pre-wrap",
          wordBreak: "break-word",
        }}
      >
        {children}
      </div>
    </div>
  );
}

// ---- Chip de tema ----
function TemaChip({ tema, active, onClick, small }) {
  const cor = TEMA_COR[tema] || C.laranja;
  return (
    <button
      onClick={onClick}
      style={{
        border: `2px solid ${cor}`,
        background: active ? cor : "transparent",
        color: active ? C.branco : cor,
        borderRadius: 999,
        padding: small ? "5px 11px" : "7px 14px",
        fontSize: small ? 12.5 : 13.5,
        fontWeight: 700,
        cursor: "pointer",
        whiteSpace: "nowrap",
        flexShrink: 0,
      }}
    >
      {tema}
    </button>
  );
}

// ============================ APP ============================
export default function App() {
  const [tab, setTab] = useState("conversar");
  const [ideias, setIdeias] = useState([]);
  const [carregando, setCarregando] = useState(true);

  const [msgs, setMsgs] = useState([
    {
      role: "assistant",
      content:
        "Salve! Eu sou o Sol ☀️, o agente da Juventude 40 Graus. Bora transformar o que te incomoda numa ideia de verdade pra juventude do Ceará?\n\nSe você pudesse mudar UMA coisa pra galera jovem da sua cidade, o que seria?",
    },
  ]);
  const [input, setInput] = useState("");
  const [pensando, setPensando] = useState(false);

  const [rascunho, setRascunho] = useState(null);
  const [extraindo, setExtraindo] = useState(false);
  const [enviada, setEnviada] = useState(false);
  const [copiado, setCopiado] = useState(false);
  const [session, setSession] = useState(null);

  const scrollRef = useRef(null);

  useEffect(() => {
    (async () => {
      setIdeias(await listMural());
      setCarregando(false);
    })();
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));
    return () => sub.subscription.unsubscribe();
  }, []);
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [msgs, pensando]);

  const iniciou = msgs.some((m) => m.role === "user");

  async function enviarTexto(texto) {
    const t = (texto || "").trim();
    if (!t || pensando) return;
    const novo = [...msgs, { role: "user", content: t }];
    setMsgs(novo);
    setInput("");
    setPensando(true);
    try {
      const r = await callAgent(novo.map((m) => ({ role: m.role, content: m.content })), SYSTEM_CHAT);
      setMsgs([...novo, { role: "assistant", content: r || "Bora, me conta mais!" }]);
    } catch {
      setMsgs([
        ...novo,
        { role: "assistant", content: "Opa, fiquei sem sinal um instante 📡. Tenta de novo — ou já toca em Enviar minha proposta que a gente registra." },
      ]);
    } finally {
      setPensando(false);
    }
  }

  async function iniciarEnvio() {
    setExtraindo(true);
    setRascunho(null);
    let draft = { titulo: "", tema: "Outro", problema: "", proposta: "", beneficiarios: "", nome: "", cidade: "", idade: "" };
    try {
      const conversa = msgs.map((m) => (m.role === "user" ? "JOVEM: " : "SOL: ") + m.content).join("\n");
      const out = await callAgent([{ role: "user", content: conversa }], SYSTEM_EXTRACT);
      const parsed = JSON.parse(out.replace(/```json/gi, "").replace(/```/g, "").trim());
      draft = { ...draft, ...parsed };
      if (!TEMAS.includes(draft.tema)) draft.tema = "Outro";
    } catch {
      /* segue com rascunho vazio pra preencher na mão */
    } finally {
      setRascunho(draft);
      setExtraindo(false);
    }
  }

  async function confirmarEnvio() {
    await saveIdeia(rascunho);
    setIdeias(await listMural());
    setRascunho(null);
    setEnviada(true);
  }

  return (
    <div style={{ minHeight: "100vh", background: C.laranjaEsc, display: "flex", justifyContent: "center", fontFamily: "'Inter', system-ui, sans-serif", color: C.tinta }}>
      <style>{`
        @font-face { font-family:'Boldonse'; src:url(data:font/ttf;base64,) format('truetype'); font-weight:normal; font-display:swap; }
        @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        * { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
        .hero { font-family:'Boldonse','Arial Black',system-ui,sans-serif; font-weight:400; letter-spacing:.5px; }
        .disp { font-family:'Baloo 2','Arial Rounded MT Bold',system-ui,sans-serif; font-weight:800; letter-spacing:0; }
        button:focus-visible, input:focus-visible, textarea:focus-visible {
          outline:3px solid ${C.tinta}; outline-offset:2px;
        }
        .scroll::-webkit-scrollbar{ width:7px; } .scroll::-webkit-scrollbar-thumb{ background:${C.cremeD}; border-radius:8px; }
        @media (prefers-reduced-motion: reduce){ .glow{ animation:none !important; } .rise{ animation:none !important; } }
        @keyframes glow{ 0%,100%{ box-shadow:0 0 0 0 rgba(248,176,10,.55);} 50%{ box-shadow:0 0 22px 5px rgba(248,176,10,.8);} }
        @keyframes rise{ from{ opacity:0; transform:translateY(8px);} to{ opacity:1; transform:none;} }
        .rise{ animation:rise .3s ease both; }
      `}</style>

      <div style={{ width: "100%", maxWidth: 460, minHeight: "100vh", background: C.creme, display: "flex", flexDirection: "column", position: "relative", boxShadow: "0 0 40px rgba(0,0,0,.25)" }}>
        {/* ---------- Top bar slim ---------- */}
        <header style={{ ...SUNBURST, display: "flex", alignItems: "center", gap: 9, padding: "11px 16px", position: "sticky", top: 0, zIndex: 10 }}>
          <CearaOutline size={30} />
          <div className="disp" style={{ fontSize: 20, color: C.branco, textShadow: `1.5px 1.5px 0 ${C.laranjaEsc}`, lineHeight: 1 }}>
            JUVENTUDE <span style={{ color: C.amarelo }}>40°</span>
          </div>
          <div style={{ marginLeft: "auto" }}>
            <Sol size={30} />
          </div>
        </header>

        {/* ---------- Conteúdo ---------- */}
        <main className="scroll" style={{ flex: 1, overflowY: "auto", display: "flex", flexDirection: "column", minHeight: 0 }}>
          {tab === "conversar" && (
            <ConversarView
              msgs={msgs}
              iniciou={iniciou}
              pensando={pensando}
              extraindo={extraindo}
              input={input}
              setInput={setInput}
              scrollRef={scrollRef}
              onEnviar={() => enviarTexto(input)}
              onQuick={(tema) => enviarTexto(`Quero falar sobre ${tema.toLowerCase()} na minha cidade.`)}
              onProposta={iniciarEnvio}
            />
          )}

          {tab === "mural" && <MuralView ideias={ideias} carregando={carregando} />}

          {tab === "entregar" &&
            (session ? (
              <EntregarView onSair={() => supabase.auth.signOut()} />
            ) : (
              <LoginView
                onEntrar={async (email, senha) => {
                  const { error } = await supabase.auth.signInWithPassword({ email, password: senha });
                  return !error;
                }}
              />
            ))}
        </main>

        {/* ---------- Navegação inferior ---------- */}
        <nav style={{ display: "flex", background: C.branco, borderTop: `1.5px solid ${C.cremeD}`, paddingBottom: "env(safe-area-inset-bottom)" }}>
          {[
            ["conversar", "Conversar", "💬"],
            ["mural", "Mural", "🔥"],
            ["entregar", "Entregar", "🔒"],
          ].map(([k, label, ic]) => {
            const on = tab === k;
            return (
              <button
                key={k}
                onClick={() => setTab(k)}
                style={{
                  flex: 1,
                  padding: "9px 0 10px",
                  border: "none",
                  background: "transparent",
                  cursor: "pointer",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 2,
                  borderTop: `3px solid ${on ? C.vermelho : "transparent"}`,
                  color: on ? C.vermelho : C.tintaSoft,
                }}
              >
                <span style={{ fontSize: 19, opacity: on ? 1 : 0.55 }}>{ic}</span>
                <span className="disp" style={{ fontSize: 12.5 }}>{label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {rascunho && <RevisaoModal rascunho={rascunho} setRascunho={setRascunho} onCancelar={() => setRascunho(null)} onConfirmar={confirmarEnvio} />}
      {enviada && <SucessoModal onFechar={() => { setEnviada(false); setTab("mural"); }} />}
    </div>
  );
}

// ============================ CONVERSAR ============================
function ConversarView({ msgs, iniciou, pensando, extraindo, input, setInput, scrollRef, onEnviar, onQuick, onProposta }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
      <div ref={scrollRef} className="scroll" style={{ flex: 1, overflowY: "auto", padding: 16, minHeight: 240 }}>
        {!iniciou && (
          <div className="rise" style={{ marginBottom: 14 }}>
            <div style={{ borderRadius: 18, overflow: "hidden", boxShadow: "0 6px 18px rgba(214,81,10,.28)", border: `2px solid ${C.dourado}` }}>
              <img src={LOGO_BANNER} alt="Juventude 40 Graus — JSB Ceará" style={{ width: "100%", display: "block" }} />
            </div>
            <div className="hero" style={{ fontSize: 19, color: C.vermelho, marginTop: 14, lineHeight: 1.15 }}>
              SUA IDEIA<br />AQUECE A POLÍTICA
            </div>
            <p style={{ fontSize: 14, color: C.tintaSoft, marginTop: 8, lineHeight: 1.5 }}>
              Converse com o Sol, nosso agente. Ele te ajuda a virar o que você vive numa proposta de verdade — que vai direto pras mãos dos candidatos.
            </p>
            <div style={{ fontSize: 12, fontWeight: 700, color: C.tintaSoft, marginTop: 14, marginBottom: 7, textTransform: "uppercase", letterSpacing: 1 }}>
              Começa por um tema
            </div>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 7 }}>
              {["Educação", "Trabalho e Renda", "Cultura e Esporte", "Saúde e Saúde Mental", "Mobilidade e Cidade"].map((t) => (
                <TemaChip key={t} tema={t} small onClick={() => onQuick(t)} />
              ))}
            </div>
            <div style={{ height: 18 }} />
          </div>
        )}

        {msgs.map((m, i) => (
          <Bubble key={i} role={m.role}>{m.content}</Bubble>
        ))}
        {pensando && <Bubble role="assistant"><span style={{ opacity: 0.55 }}>digitando…</span></Bubble>}
      </div>

      {/* barra de envio fixa */}
      <div style={{ borderTop: `1.5px solid ${C.cremeD}`, background: C.creme, padding: 12 }}>
        {iniciou && (
          <button
            onClick={onProposta}
            disabled={extraindo}
            className="glow"
            style={{ animation: "glow 2.2s infinite", width: "100%", marginBottom: 10, padding: 13, borderRadius: 14, border: `2px solid ${C.tinta}`, background: C.dourado, color: C.tinta, fontWeight: 800, fontSize: 15, cursor: "pointer" }}
          >
            {extraindo ? "Organizando sua proposta…" : "✋ Enviar minha proposta 🔥"}
          </button>
        )}
        <div style={{ display: "flex", gap: 8 }}>
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && onEnviar()}
            placeholder="Escreve aqui…"
            style={{ flex: 1, padding: "12px 14px", borderRadius: 14, border: `1.5px solid ${C.cremeD}`, fontSize: 15, background: C.branco, color: C.tinta }}
          />
          <button
            onClick={onEnviar}
            disabled={pensando}
            style={{ padding: "0 18px", borderRadius: 14, border: "none", background: C.vermelho, color: C.branco, fontWeight: 800, fontSize: 16, cursor: "pointer" }}
          >
            ▶
          </button>
        </div>
      </div>
    </div>
  );
}

// ============================ MURAL ============================
function MuralView({ ideias, carregando }) {
  const [filtro, setFiltro] = useState(null);
  const n = ideias.length;
  const temp = (34 + n * 0.3).toFixed(1);
  const quente = Number(temp) >= 40;
  const prog = Math.min(100, ((Number(temp) - 34) / 8) * 100);
  const cidades = new Set(ideias.map((i) => (i.cidade || "").trim().toLowerCase()).filter(Boolean)).size;
  const temasComIdeias = TEMAS.filter((t) => ideias.some((i) => i.tema === t));
  const lista = filtro ? ideias.filter((i) => i.tema === filtro) : ideias;

  return (
    <div style={{ display: "flex", flexDirection: "column", flex: 1, minHeight: 0 }}>
      <div style={{ padding: 16, paddingBottom: 8 }}>
        {/* termômetro */}
        <div style={{ ...SUNBURST, borderRadius: 20, padding: "16px 18px 18px", color: C.branco, textAlign: "center", boxShadow: "0 6px 18px rgba(214,81,10,.3)" }}>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 2, textTransform: "uppercase", opacity: 0.9 }}>Termômetro da juventude</div>
          <div className="hero" style={{ fontSize: 52, lineHeight: 1, margin: "6px 0 2px", textShadow: `2px 3px 0 ${C.laranjaEsc}` }}>
            {temp}°{quente ? " 🔥" : ""}
          </div>
          <div style={{ height: 9, background: "rgba(0,0,0,.22)", borderRadius: 999, overflow: "hidden", margin: "8px 4px 10px" }}>
            <div style={{ width: `${prog}%`, height: "100%", background: C.amarelo, borderRadius: 999, transition: "width .5s" }} />
          </div>
          <div style={{ display: "flex", justifyContent: "center", gap: 18, fontSize: 12.5, fontWeight: 600 }}>
            <span><b className="disp" style={{ fontSize: 16 }}>{n}</b> {n === 1 ? "ideia" : "ideias"}</span>
            <span><b className="disp" style={{ fontSize: 16 }}>{temasComIdeias.length}</b> temas</span>
            <span><b className="disp" style={{ fontSize: 16 }}>{cidades}</b> {cidades === 1 ? "cidade" : "cidades"}</span>
          </div>
        </div>
      </div>

      {temasComIdeias.length > 0 && (
        <div className="scroll" style={{ display: "flex", gap: 7, overflowX: "auto", padding: "0 16px 10px" }}>
          <TemaChip tema="Todas" active={!filtro} small onClick={() => setFiltro(null)} />
          {temasComIdeias.map((t) => (
            <TemaChip key={t} tema={t} active={filtro === t} small onClick={() => setFiltro(t)} />
          ))}
        </div>
      )}

      <div className="scroll" style={{ overflowY: "auto", flex: 1, padding: "0 16px 18px" }}>
        {carregando && <p style={{ textAlign: "center", opacity: 0.55, marginTop: 30 }}>Carregando o mural…</p>}
        {!carregando && lista.length === 0 && (
          <div style={{ textAlign: "center", marginTop: 40, opacity: 0.75 }}>
            <Sol size={54} />
            <p style={{ fontSize: 15, marginTop: 8 }}>Ainda não tem ideia por aqui.</p>
            <p style={{ fontSize: 13 }}>Vai em <b>Conversar</b> e solta a primeira faísca 🔥</p>
          </div>
        )}
        {lista.map((idea) => (
          <IdeiaCard key={idea.id} idea={idea} />
        ))}
      </div>
    </div>
  );
}

function IdeiaCard({ idea }) {
  const cor = TEMA_COR[idea.tema] || C.laranja;
  const autor = [idea.nome, idea.cidade, idea.idade && `${idea.idade} anos`].filter(Boolean).join(" · ");
  return (
    <div className="rise" style={{ background: C.branco, border: `1.5px solid ${C.cremeD}`, borderLeft: `7px solid ${cor}`, borderRadius: 14, padding: "12px 14px", marginBottom: 10, boxShadow: "0 1px 3px rgba(31,25,23,.06)" }}>
      <span style={{ fontSize: 10.5, fontWeight: 800, color: cor, textTransform: "uppercase", letterSpacing: 0.6 }}>{idea.tema}</span>
      <div className="disp" style={{ fontSize: 18, color: C.tinta, lineHeight: 1.1, margin: "2px 0 6px" }}>{idea.titulo || "Proposta sem título"}</div>
      {idea.problema && <p style={{ fontSize: 13.5, margin: "0 0 4px", color: C.tintaSoft }}><b style={{ color: C.tinta }}>Problema:</b> {idea.problema}</p>}
      {idea.proposta && <p style={{ fontSize: 13.5, margin: "0 0 6px", color: C.tintaSoft }}><b style={{ color: C.tinta }}>Proposta:</b> {idea.proposta}</p>}
      <div style={{ fontSize: 11.5, opacity: 0.6 }}>{autor || "Anônimo"}</div>
    </div>
  );
}

// ============================ LOGIN ============================

function LoginView({ onEntrar }) {
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");
  const [carregando, setCarregando] = useState(false);
  const inp = { marginTop: 10, width: "100%", maxWidth: 300, padding: "12px 14px", borderRadius: 14, border: `2px solid ${C.cremeD}`, fontSize: 15, background: C.branco, color: C.tinta, textAlign: "center" };
  const tentar = async () => {
    if (!email || !senha) return;
    setCarregando(true);
    const ok = await onEntrar(email.trim(), senha);
    setCarregando(false);
    if (!ok) { setErro("E-mail ou senha incorretos."); setSenha(""); }
  };
  return (
    <div className="rise" style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: 24 }}>
      <div style={{ width: 74, height: 74, borderRadius: "50%", ...SUNBURST, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 32, boxShadow: "0 6px 16px rgba(214,81,10,.3)" }}>🔒</div>
      <div className="disp" style={{ fontSize: 24, color: C.vermelho, marginTop: 14 }}>Área da coordenação</div>
      <p style={{ fontSize: 13.5, color: C.tintaSoft, marginTop: 6, maxWidth: 300, lineHeight: 1.5 }}>
        O dossiê da juventude é privado. Só a coordenação da JSB acessa e entrega aos candidatos.
      </p>
      <input type="email" value={email} onChange={(e) => { setEmail(e.target.value); setErro(""); }} placeholder="E-mail" style={inp} />
      <input type="password" value={senha} onChange={(e) => { setSenha(e.target.value); setErro(""); }} onKeyDown={(e) => e.key === "Enter" && tentar()} placeholder="Senha" style={inp} />
      {erro && <div style={{ color: C.vermelho, fontSize: 13, marginTop: 8, fontWeight: 700 }}>{erro}</div>}
      <button onClick={tentar} disabled={carregando} className="disp" style={{ marginTop: 14, width: "100%", maxWidth: 300, padding: 13, borderRadius: 14, border: `2px solid ${C.tinta}`, background: C.dourado, color: C.tinta, fontSize: 18, cursor: "pointer" }}>
        {carregando ? "Entrando…" : "Entrar"}
      </button>
    </div>
  );
}

// ============================ ENTREGAR ============================

function EntregarView({ onSair }) {
  const [ideias, setIdeias] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [copiado, setCopiado] = useState(false);
  useEffect(() => {
    (async () => { setIdeias(await listDossie()); setCarregando(false); })();
  }, []);
  const porTema = TEMAS.map((t) => ({ tema: t, itens: ideias.filter((i) => i.tema === t) })).filter((g) => g.itens.length);
  const cidades = new Set(ideias.map((i) => (i.cidade || "").trim().toLowerCase()).filter(Boolean)).size;
  const copiar = async () => {
    try { await navigator.clipboard.writeText(montarRelatorio(ideias)); setCopiado(true); setTimeout(() => setCopiado(false), 2500); } catch { setCopiado(false); }
  };
  return (
    <div className="scroll rise" style={{ overflowY: "auto", flex: 1, padding: 16 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8 }}>
        <div className="disp" style={{ fontSize: 23, color: C.vermelho }}>Dossiê da juventude</div>
        <button onClick={onSair} style={{ fontSize: 12, fontWeight: 700, padding: "5px 12px", borderRadius: 999, border: `2px solid ${C.tinta}`, background: "transparent", color: C.tinta, cursor: "pointer" }}>Sair</button>
      </div>
      <div style={{ display: "flex", gap: 8, margin: "12px 0 14px" }}>
        {[[ideias.length, "propostas"], [porTema.length, "temas"], [cidades, "cidades"]].map(([v, l], i) => (
          <div key={i} style={{ flex: 1, background: C.branco, border: `1.5px solid ${C.cremeD}`, borderRadius: 12, padding: "10px 6px", textAlign: "center" }}>
            <div className="disp" style={{ fontSize: 22, color: C.laranja }}>{v}</div>
            <div style={{ fontSize: 11, color: C.tintaSoft, fontWeight: 600 }}>{l}</div>
          </div>
        ))}
      </div>
      <button onClick={copiar} disabled={!ideias.length} className="disp" style={{ width: "100%", padding: 13, borderRadius: 14, border: `2px solid ${C.tinta}`, background: ideias.length ? C.dourado : C.cremeD, color: C.tinta, fontSize: 16, cursor: ideias.length ? "pointer" : "not-allowed", marginBottom: 18 }}>
        {copiado ? "✓ Relatório copiado!" : "Copiar relatório completo"}
      </button>
      {carregando && <p style={{ opacity: 0.6, fontSize: 14 }}>Carregando…</p>}
      {!carregando && porTema.length === 0 && <p style={{ opacity: 0.7, fontSize: 14 }}>Nenhuma proposta ainda.</p>}
      {porTema.map((g) => (
        <div key={g.tema} style={{ marginBottom: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
            <span className="disp" style={{ fontSize: 16, color: TEMA_COR[g.tema] }}>{g.tema}</span>
            <span style={{ fontSize: 11, fontWeight: 800, background: TEMA_COR[g.tema], color: "#fff", borderRadius: 999, padding: "1px 9px" }}>{g.itens.length}</span>
          </div>
          {g.itens.map((i) => (
            <div key={i.id} style={{ fontSize: 13.5, borderLeft: `3px solid ${C.cremeD}`, paddingLeft: 10, marginBottom: 8, color: C.tintaSoft }}>
              <b style={{ color: C.tinta }}>{i.titulo}</b>{i.proposta ? ` — ${i.proposta}` : ""}
              {(i.nome || i.cidade) && <span style={{ display: "block", fontSize: 11, opacity: 0.6, marginTop: 2 }}>{[i.nome, i.cidade, i.idade && `${i.idade} anos`].filter(Boolean).join(" · ")}</span>}
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

function montarRelatorio(ideias) {
  const linhas = [];
  linhas.push("JUVENTUDE 40 GRAUS — DOSSIÊ DE POLÍTICAS PÚBLICAS DE JUVENTUDE");
  linhas.push("JSB Ceará · ciclo 2026");
  linhas.push(`Total de propostas: ${ideias.length}`);
  linhas.push("=".repeat(56));
  TEMAS.forEach((t) => {
    const itens = ideias.filter((i) => i.tema === t);
    if (!itens.length) return;
    linhas.push("");
    linhas.push(`## ${t.toUpperCase()} (${itens.length})`);
    itens.forEach((i, idx) => {
      linhas.push("");
      linhas.push(`${idx + 1}. ${i.titulo || "(sem título)"}`);
      if (i.problema) linhas.push(`   Problema: ${i.problema}`);
      if (i.proposta) linhas.push(`   Proposta: ${i.proposta}`);
      if (i.beneficiarios) linhas.push(`   Beneficia: ${i.beneficiarios}`);
      const autor = [i.nome, i.cidade, i.idade && `${i.idade} anos`].filter(Boolean).join(", ");
      if (autor) linhas.push(`   Por: ${autor}`);
    });
  });
  return linhas.join("\n");
}

