function Overlay({ children }) {
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(20,15,13,.55)", display: "flex", alignItems: "center", justifyContent: "center", padding: 14, zIndex: 50 }}>
      <div className="scroll" style={{ width: "100%", maxWidth: 430, maxHeight: "90vh", overflowY: "auto", background: C.creme, borderRadius: 20, padding: 20, border: `3px solid ${C.tinta}` }}>
        {children}
      </div>
    </div>
  );
}
